const INCLUIR_EMBUDOS = [13934292,13634751,13848103];
const EXCLUIR_USUARIOS = [15352691,15839060];
function parse(raw) {
  if (raw && typeof raw.data === 'string') { try { return JSON.parse(raw.data); } catch(e) {} }
  return raw || {};
}
const pipesData = parse($('HTTP Pipelines3').first().json);
const tagsData  = parse($('HTTP Tags3').first().json);
const usersData = parse($('HTTP Users3').first().json);
const pipelines = ((pipesData._embedded || {}).pipelines || []).filter(p => INCLUIR_EMBUDOS.includes(p.id)).map(p => {
  const stages = ((p._embedded || {}).statuses || []).filter(s => s.type !== 10000).sort((a,b)=>(a.sort||0)-(b.sort||0)).map(s=>({id:s.id,name:s.name}));
  return { id: p.id, name: p.name, stages };
});
const tags   = ((tagsData._embedded  || {}).tags  || []).map(t => ({ id: t.id, name: t.name })).sort((a, b) => a.name.localeCompare(b.name, 'es'));
const agents = ((usersData._embedded || {}).users || []).filter(u => !EXCLUIR_USUARIOS.includes(u.id)).map(u => ({ id: u.id, name: u.name }));
return [{ json: { type: 'scan_result', pipelines, tags, agents } }];

