// Lee body del webhook, config de Kommo y el mapeo de embudos
const body = $('Webhook3').first().json.body;
const cfg = $('Config4').first().json;
const mapeo = $('Config Mapeo2').first().json.embudos;
const canalesCfg = $('Config Mapeo2').first().json.canales || [];
const nombreCanal = { sin_canal: 'Sin etiqueta de canal' };
canalesCfg.forEach(c => { nombreCanal[c.clave] = c.nombre; });
// Canal = primera regla de Config Mapeo cuyas etiquetas (o patrones) coincidan con las etiquetas del lead.
function canalDeLead(lead) {
  const tags = ((lead._embedded && lead._embedded.tags) || []).map(t => String(t.name));
  const bajas = tags.map(t => t.toLowerCase());
  for (const c of canalesCfg) {
    const nombres = (c.etiquetas || []).map(x => String(x).toLowerCase());
    const pats = (c.patrones || []).map(p => new RegExp(p, 'i'));
    if (bajas.some(t => nombres.includes(t)) || tags.some(t => pats.some(re => re.test(t)))) return c.clave;
  }
  return 'sin_canal';
}
const porCanal = {};

if (!body || body.type !== 'leads') {
  throw new Error(`Se esperaba type="leads" pero llego type="${body && body.type}". Revisa el cableado de Switch Tipo2: su salida 'leads' (indice 1) debe ir a Config Mapeo.`);
}
if (!body.date_from || !body.date_to) {
  throw new Error('Faltan date_from/date_to en la solicitud. Sin esto, el filtro de fecha hacia Kommo queda invalido y regresa TODOS los leads de la cuenta sin filtrar.');
}

const filterBy = (body.filter_by === 'closed_at') ? 'closed_at' : (body.filter_by === 'enrolled_at' ? 'enrolled_at' : 'created_at');

function toUnixStart(dateStr) {
  return Math.floor(new Date(`${dateStr}T00:00:00-06:00`).getTime() / 1000);
}
function toUnixEnd(dateStr) {
  return Math.floor(new Date(`${dateStr}T23:59:59-06:00`).getTime() / 1000);
}

const qp = [];
function addParam(key, value) { qp.push(encodeURIComponent(key) + '=' + encodeURIComponent(value)); }
addParam('with', 'loss_reason,tags,contacts,company');
addParam('limit', '250');
if (filterBy !== 'enrolled_at') {
  addParam(`filter[${filterBy}][from]`, toUnixStart(body.date_from));
  addParam(`filter[${filterBy}][to]`, toUnixEnd(body.date_to));
}
if (body.agent_ids && body.agent_ids.length) {
  body.agent_ids.forEach(id => addParam('filter[responsible_user_id][]', id));
}
if (body.pipeline_ids && body.pipeline_ids.length) {
  body.pipeline_ids.forEach(id => addParam('filter[pipeline_id][]', id));
}

// Filtro opcional de etiquetas: 100% manual, elegido en el dashboard (tag_ids).
// Ya no hay etiquetas forzadas por embudo (antes web_edu_dc traia Meta/Google fijo).
const tagFilterSet = (body.tag_ids && body.tag_ids.length) ? new Set(body.tag_ids.map(Number)) : null;

// Inscritos por fecha de inscripcion: leads que PASARON a una etapa de inscrito dentro del periodo (historial de etapas),
// traidos por id y conservados solo si siguen en una etapa de inscrito. Respeta los filtros de embudo y de asesor.
async function leadsInscritosEnPeriodo() {
  const hdr = { Authorization: `Bearer ${cfg.kommo_token}`, 'Content-Type': 'application/json' };
  const objetivos = [];
  for (const m of Object.values(mapeo)) {
    if (body.pipeline_ids && body.pipeline_ids.length && !body.pipeline_ids.includes(m.pipeline_id)) continue;
    for (const sid of m.ganado_ids) objetivos.push({ pipeline_id: m.pipeline_id, status_id: sid });
  }
  if (!objetivos.length) return [];
  const eqp = [];
  const addE = (k, v) => eqp.push(encodeURIComponent(k) + '=' + encodeURIComponent(v));
  addE('filter[type][0]', 'lead_status_changed');
  addE('filter[created_at][from]', toUnixStart(body.date_from));
  addE('filter[created_at][to]', toUnixEnd(body.date_to));
  objetivos.forEach((o, i) => {
    addE(`filter[value_after][leads_statuses][${i}][pipeline_id]`, o.pipeline_id);
    addE(`filter[value_after][leads_statuses][${i}][status_id]`, o.status_id);
  });
  addE('limit', '100');
  const ids = new Set();
  let urlE = `https://${cfg.kommo_subdomain}.kommo.com/api/v4/events?${eqp.join('&')}`;
  let guardE = 0;
  while (urlE && guardE < 100) {
    let r = await this.helpers.httpRequest({ method: 'GET', url: urlE, headers: hdr, json: true });
    if (!r || typeof r !== 'object') r = {};
    for (const ev of ((r._embedded && r._embedded.events) || [])) { if (ev.entity_id != null) ids.add(ev.entity_id); }
    urlE = (r._links && r._links.next && r._links.next.href) || null;
    guardE++;
  }
  const lista = [...ids];
  const out = [];
  for (let i = 0; i < lista.length; i += 100) {
    const lote = lista.slice(i, i + 100);
    const q = ['with=' + encodeURIComponent('loss_reason,tags,contacts,company'), 'limit=250'];
    lote.forEach((id, k) => q.push(`filter%5Bid%5D%5B${k}%5D=${id}`));
    let r = await this.helpers.httpRequest({ method: 'GET', url: `https://${cfg.kommo_subdomain}.kommo.com/api/v4/leads?${q.join('&')}`, headers: hdr, json: true });
    if (!r || typeof r !== 'object') r = {};
    out.push(...((r._embedded && r._embedded.leads) || []));
  }
  const ganadoPorEmbudo = {};
  for (const m of Object.values(mapeo)) ganadoPorEmbudo[m.pipeline_id] = m.ganado_ids;
  const agentes = (body.agent_ids || []).map(Number);
  return out.filter(l => (ganadoPorEmbudo[l.pipeline_id] || []).includes(l.status_id)
    && (!agentes.length || agentes.includes(Number(l.responsible_user_id))));
}

let nextUrl = `https://${cfg.kommo_subdomain}.kommo.com/api/v4/leads?${qp.join('&')}`;
let allLeads = [];
let guard = 0;
if (filterBy === 'enrolled_at') {
  allLeads = await leadsInscritosEnPeriodo.call(this);
  nextUrl = null;
}

while (nextUrl && guard < 50) {
  let resp = await this.helpers.httpRequest({
    method: 'GET',
    url: nextUrl,
    headers: { Authorization: `Bearer ${cfg.kommo_token}`, 'Content-Type': 'application/json' },
    json: true,
  });
  // Kommo regresa 204 sin cuerpo cuando no hay resultados; algunos clientes
  // HTTP internos lo devuelven como null/"" en vez de un objeto. Se normaliza
  // para no tronar el nodo en periodos/embudos sin leads.
  if (!resp || typeof resp !== 'object') resp = {};
  const pageLeads = (resp._embedded && resp._embedded.leads) || [];
  allLeads = allLeads.concat(pageLeads);
  nextUrl = (resp._links && resp._links.next && resp._links.next.href) || null;
  guard++;
}

function buildPositionMap(stageOrder) {
  const map = {};
  stageOrder.forEach((stageId, idx) => { map[stageId] = idx; });
  return map;
}

// ---------------------------------------------------------------------------
// Credito historico para leads PERDIDOS: por peticion explicita de Manu (audio
// del 3-jul-2026), un lead que se marca "perdido" hoy pierde todo su credito
// de efectivo/cotizacion aunque de verdad haya llegado ahi antes de perderse.
// Kommo no guarda "por cuales etapas paso" en el lead en si (/api/v4/leads
// solo trae su etapa actual/final) -- hay que reconstruirlo con el historial
// de cambios de estatus via /api/v4/events (mismo mecanismo que Calcular
// Volumen Llamadas ya usa para las llamadas).
//
// Actualizado 3-jul-2026 tras un 400 real en produccion: el filtro
// filter[entity_id] de /api/v4/events NO acepta notacion de arreglo, es un
// solo string de hasta 10 IDs separados por coma (confirmado contra la doc
// oficial: developers.kommo.com/reference/events-list). La forma de
// value_after (value_after[0].lead_status.id/.pipeline_id) tambien quedo
// confirmada contra esa misma documentacion -- eso ya no es una suposicion.
//
// Decision explicita (3-jul-2026): este credito historico solo aplica a
// "efectivo" y "cotizacion". NO aplica a "calificado" -- se deja como esta
// (solo cuenta si el lead sigue actualmente en esa etapa o mas adelante).
// ---------------------------------------------------------------------------

async function fetchStatusHistory(leadIds) {
  const ids = [...leadIds];
  if (!ids.length) return [];
  const out = [];
  // Confirmado contra la documentacion oficial de Kommo (developers.kommo.com/
  // reference/events-list): filter[entity_id] acepta UN string de hasta 10 IDs
  // separados por coma -- NO notacion de arreglo filter[entity_id][0]=X&[1]=Y.
  // Mandar mas de 10, o mandarlo como arreglo, es lo que causaba el 400.
  const BATCH = 10;
  for (let i = 0; i < ids.length; i += BATCH) {
    const batch = ids.slice(i, i + BATCH);
    const eqp = [];
    function addE(k, v) { eqp.push(encodeURIComponent(k) + '=' + encodeURIComponent(v)); }
    addE('filter[type]', 'lead_status_changed');
    addE('filter[entity]', 'lead');
    addE('filter[entity_id]', batch.join(','));
    addE('limit', '250');
    let nextUrl = `https://${cfg.kommo_subdomain}.kommo.com/api/v4/events?${eqp.join('&')}`;
    let guard = 0;
    while (nextUrl && guard < 50) {
      let resp = await this.helpers.httpRequest({
        method: 'GET',
        url: nextUrl,
        headers: { Authorization: `Bearer ${cfg.kommo_token}`, 'Content-Type': 'application/json' },
        json: true,
      });
      if (!resp || typeof resp !== 'object') resp = {};
      const page = (resp._embedded && resp._embedded.events) || [];
      out.push(...page);
      nextUrl = (resp._links && resp._links.next && resp._links.next.href) || null;
      guard++;
    }
  }
  return out;
}

function parseStatusEvent(ev) {
  const after = ev.value_after && ev.value_after[0];
  const statusObj = after && (after.lead_status || after.status || after);
  if (!statusObj || statusObj.id == null) return null;
  return {
    leadId: ev.entity_id,
    statusId: statusObj.id,
    pipelineId: statusObj.pipeline_id != null ? statusObj.pipeline_id : null,
  };
}

const resultado = {};

for (const [key, mcfg] of Object.entries(mapeo)) {
  if (body.pipeline_ids && body.pipeline_ids.length && !body.pipeline_ids.includes(mcfg.pipeline_id)) continue;

  const posMap = buildPositionMap(mcfg.stage_order);
  const efectivoPos = mcfg.efectivo != null ? posMap[mcfg.efectivo] : null;
  const cotizacionPos = mcfg.cotizacion != null ? posMap[mcfg.cotizacion] : null;
  const calificadoPos = mcfg.calificado != null ? posMap[mcfg.calificado] : null;

  const acc = {
    embudo: key,
    pipeline_id: mcfg.pipeline_id,
    total: 0,
    efectivo: 0,
    cotizacion: 0,
    calificado: 0,
    ganado: 0,
    perdido: 0,
    monto_ganado: 0,
    monto_cotizacion: 0,
    motivos_perdida: {},
    perdidos_efectivo_historico: 0,
    perdidos_cotizacion_historico: 0,
    eventos_historial_reconocidos: 0
  };

  let leadsEmbudo = allLeads.filter(l => l.pipeline_id === mcfg.pipeline_id);
  // Filtro opcional por etiquetas seleccionadas manualmente en el dashboard (aplica a cualquier embudo)
  if (tagFilterSet) {
    leadsEmbudo = leadsEmbudo.filter(l => {
      const tags = (l._embedded && l._embedded.tags) || [];
      return tags.some(t => tagFilterSet.has(Number(t.id)));
    });
  }
  acc.total = leadsEmbudo.length;

  // Historial de los perdidos: solo se pide si este embudo de verdad tiene
  // configurada una etapa "efectivo" o "cotizacion" (si no tiene ninguna, no
  // hay nada que acreditar y nos ahorramos las llamadas a Kommo).
  const perdidoIds = leadsEmbudo.filter(l => mcfg.perdido_ids.includes(l.status_id)).map(l => l.id);
  const maxPosPorLead = {};
  if (perdidoIds.length && (efectivoPos != null || cotizacionPos != null)) {
    const eventosHistorial = await fetchStatusHistory.call(this, perdidoIds);
    for (const ev of eventosHistorial) {
      const parsed = parseStatusEvent(ev);
      if (!parsed) continue;
      if (parsed.pipelineId != null && parsed.pipelineId !== mcfg.pipeline_id) continue;
      const pos = posMap[parsed.statusId];
      if (pos == null) continue;
      acc.eventos_historial_reconocidos++;
      if (maxPosPorLead[parsed.leadId] == null || pos > maxPosPorLead[parsed.leadId]) {
        maxPosPorLead[parsed.leadId] = pos;
      }
    }
  }

  for (const lead of leadsEmbudo) {
    if (mcfg.ganado_ids.includes(lead.status_id)) {
      acc.ganado++;
      acc.monto_ganado += (lead.price || 0);
      acc.efectivo++;
      if (cotizacionPos != null) { acc.cotizacion++; acc.monto_cotizacion += (lead.price || 0); }
      if (calificadoPos != null) acc.calificado++;
      continue;
    }
    if (mcfg.perdido_ids.includes(lead.status_id)) {
      acc.perdido++;
      const motivo = (lead._embedded && lead._embedded.loss_reason && lead._embedded.loss_reason[0] && lead._embedded.loss_reason[0].name) || 'Sin motivo registrado';
      acc.motivos_perdida[motivo] = (acc.motivos_perdida[motivo] || 0) + 1;
      // Credito historico: aunque hoy este perdido, si en su camino llego a
      // "efectivo" o "cotizacion" antes de perderse, cuenta ahi tambien. No
      // se le quita el conteo de "perdido" de arriba -- cuenta en los dos.
      const maxPos = maxPosPorLead[lead.id];
      if (maxPos != null) {
        if (efectivoPos != null && maxPos >= efectivoPos) { acc.efectivo++; acc.perdidos_efectivo_historico++; }
        if (cotizacionPos != null && maxPos >= cotizacionPos) { acc.cotizacion++; acc.perdidos_cotizacion_historico++; acc.monto_cotizacion += (lead.price || 0); }
      }
      continue;
    }
    const leadPos = posMap[lead.status_id];
    if (leadPos == null) continue;
    if (efectivoPos != null && leadPos >= efectivoPos) acc.efectivo++;
    if (cotizacionPos != null && leadPos >= cotizacionPos) { acc.cotizacion++; acc.monto_cotizacion += (lead.price || 0); }
    if (calificadoPos != null && leadPos >= calificadoPos) acc.calificado++;
  }

  // Canales: de los leads de este embudo, cuantos entraron, llegaron a cita y se inscribieron, por canal.
  for (const lead of leadsEmbudo) {
    const ck = canalDeLead(lead);
    const ch = porCanal[ck] || (porCanal[ck] = { clave: ck, nombre: nombreCanal[ck], leads: 0, citas: 0, inscritos: 0, monto: 0 });
    ch.leads++;
    if (mcfg.ganado_ids.includes(lead.status_id)) { ch.inscritos++; ch.citas++; ch.monto += (lead.price || 0); continue; }
    const posLead = posMap[lead.status_id];
    if (posLead != null && calificadoPos != null && posLead >= calificadoPos) ch.citas++;
  }
  resultado[key] = acc;
}

// ---------------------------------------------------------------------------
// Leads por periodo: dos desgloses de la MISMA poblacion de leads (por
// asesor y por embudo) que por definicion tienen que sumar igual -- pedido
// explicito de Manu para medir capacidad instalada (referencia: 250
// leads/mes por asesor) y avance de meta de leads entrantes por embudo.
//
// Para que las sumas coincidan de verdad, "leads por asesor" se calcula
// sobre la MISMA poblacion que ya usa el desglose por embudo de arriba:
// leads cuyo pipeline_id es uno de los embudos incluidos (respeta
// pipeline_ids si se filtro) y que pasan el mismo filtro de etiquetas.
// "leads por embudo" simplemente reutiliza el total que ya se calculo
// arriba por cada embudo (acc.total), no se vuelve a calcular aparte.
// ---------------------------------------------------------------------------
const pipelineIdIncluido = {};
for (const [key, mcfg] of Object.entries(mapeo)) {
  if (body.pipeline_ids && body.pipeline_ids.length && !body.pipeline_ids.includes(mcfg.pipeline_id)) continue;
  pipelineIdIncluido[mcfg.pipeline_id] = true;
}

let leadsParaPeriodo = allLeads.filter(l => pipelineIdIncluido[l.pipeline_id]);
if (tagFilterSet) {
  leadsParaPeriodo = leadsParaPeriodo.filter(l => {
    const tags = (l._embedded && l._embedded.tags) || [];
    return tags.some(t => tagFilterSet.has(Number(t.id)));
  });
}

const leadsPorAsesor = {};
for (const lead of leadsParaPeriodo) {
  const uid = lead.responsible_user_id || 0;
  leadsPorAsesor[uid] = (leadsPorAsesor[uid] || 0) + 1;
}

const leadsPorEmbudo = {};
for (const [key, acc] of Object.entries(resultado)) {
  leadsPorEmbudo[key] = acc.total;
}

// ---------------------------------------------------------------------------
// Desglose de leads ganados (lista plana, no agrupada por embudo) -- pedido
// explicito para mostrar cada venta individual: lead, contacto, monto,
// compania, responsable, etiquetas. Kommo solo regresa el ID de contacto/
// compania en el lead (via with=contacts,company), el nombre hay que
// resolverlo aparte con un fetch por lote -- mismo patron que ya usa este
// flujo para las notas de llamadas (filter[id][N]=X, tope de lote 100).
// ---------------------------------------------------------------------------
const pipelineIdToGanadoStatus = {};
for (const [key, mcfg] of Object.entries(mapeo)) pipelineIdToGanadoStatus[mcfg.pipeline_id] = mcfg.ganado_ids;

const pipelineIdToKeyGanados = {};
for (const [key, mcfg] of Object.entries(mapeo)) pipelineIdToKeyGanados[mcfg.pipeline_id] = key;

const leadsGanados = allLeads.filter(l => (pipelineIdToGanadoStatus[l.pipeline_id] || []).includes(l.status_id));

const contactIdsGanados = new Set();
const companyIdsGanados = new Set();
for (const lead of leadsGanados) {
  const contactos = (lead._embedded && lead._embedded.contacts) || [];
  const principal = contactos.find(c => c.is_main) || contactos[0];
  if (principal) contactIdsGanados.add(principal.id);
  const companias = (lead._embedded && lead._embedded.companies) || [];
  if (companias[0]) companyIdsGanados.add(companias[0].id);
}

async function fetchNombresPorId(entityTypePlural, idsSet) {
  const ids = [...idsSet];
  const out = {};
  if (!ids.length) return out;
  const BATCH = 100;
  for (let i = 0; i < ids.length; i += BATCH) {
    const batch = ids.slice(i, i + BATCH);
    const qp = batch.map((id, idx) => `filter%5Bid%5D%5B${idx}%5D=${id}`).join('&');
    const url = `https://${cfg.kommo_subdomain}.kommo.com/api/v4/${entityTypePlural}?${qp}&limit=250`;
    let resp = await this.helpers.httpRequest({
      method: 'GET', url,
      headers: { Authorization: `Bearer ${cfg.kommo_token}`, 'Content-Type': 'application/json' },
      json: true,
    });
    if (!resp || typeof resp !== 'object') resp = {};
    const items = (resp._embedded && resp._embedded[entityTypePlural]) || [];
    for (const it of items) out[it.id] = it.name;
  }
  return out;
}

const [nombresContactos, nombresCompanias] = await Promise.all([
  fetchNombresPorId.call(this, 'contacts', contactIdsGanados),
  fetchNombresPorId.call(this, 'companies', companyIdsGanados),
]);

const ganadosDetalle = leadsGanados.map(lead => {
  const contactos = (lead._embedded && lead._embedded.contacts) || [];
  const principal = contactos.find(c => c.is_main) || contactos[0];
  const companias = (lead._embedded && lead._embedded.companies) || [];
  const tags = ((lead._embedded && lead._embedded.tags) || []).map(t => t.name);
  return {
    lead_id: lead.id,
    embudo: pipelineIdToKeyGanados[lead.pipeline_id] || null,
    nombre_lead: lead.name || `Lead ${lead.id}`,
    nombre_contacto: principal ? (nombresContactos[principal.id] || null) : null,
    monto: lead.price || 0,
    compania: companias[0] ? (nombresCompanias[companias[0].id] || null) : null,
    responsible_user_id: lead.responsible_user_id || null,
    etiquetas: tags,
    canal: nombreCanal[canalDeLead(lead)],
  };
}).sort((a, b) => b.monto - a.monto);

return [{ json: {
  periodo: { from: body.date_from, to: body.date_to, filtrado_por: filterBy },
  total_leads_extraidos: allLeads.length,
  por_embudo: resultado,
  ganados_detalle: ganadosDetalle,
  leads_por_asesor: leadsPorAsesor,
  leads_por_embudo: leadsPorEmbudo,
  por_canal: Object.values(porCanal).sort((a, b) => (b.inscritos - a.inscritos) || (b.leads - a.leads))
}}];

// Oportunidades calientes: leads que HOY estan en alguna etapa caliente de cada embudo
// (PROSPECTO HOT, CITAS HOT, DOCUMENTOS HOT, EVALUACION, CIERRE HOT; ver `calientes` en Config Mapeo).
// Mantiene los nombres de campos del cross-tab de calificados para no romper al dashboard.
const body = $('Webhook3').first().json.body;
const cfg = $('Config4').first().json;
const mapeo = $('Config Mapeo2').first().json.embudos;

if (!body || body.type !== 'leads' || body.view !== 'qualified_crosstab') {
  throw new Error(`Se esperaba type="leads" y view="qualified_crosstab" pero llego type="${body && body.type}", view="${body && body.view}".`);
}

function toUnixStart(dateStr) { return Math.floor(new Date(`${dateStr}T00:00:00-06:00`).getTime() / 1000); }
function toUnixEnd(dateStr) { return Math.floor(new Date(`${dateStr}T23:59:59-06:00`).getTime() / 1000); }

const embudosCalientes = Object.entries(mapeo).filter(([k, m]) => m.cross_tab_calificados && (m.calientes || []).length);
const embudosExcluidos = Object.entries(mapeo).filter(([k, m]) => !m.cross_tab_calificados || !(m.calientes || []).length).map(([k]) => k);

// Filtros opcionales del dashboard: etiquetas, agentes y embudos
const tagFilterSet = (body.tag_ids && body.tag_ids.length) ? new Set(body.tag_ids.map(Number)) : null;
const agentIds = (body.agent_ids || []).map(Number);
const pipelineIds = (body.pipeline_ids || []).map(Number);

const resultado = {};
const detalleRaw = [];

for (const [key, mcfg] of embudosCalientes) {
  if (pipelineIds.length && !pipelineIds.includes(mcfg.pipeline_id)) continue;

  const qp = [];
  const addParam = (k, v) => qp.push(encodeURIComponent(k) + '=' + encodeURIComponent(v));
  addParam('limit', '250');
  addParam('with', 'tags,contacts');
  mcfg.calientes.forEach((s, i) => {
    addParam(`filter[statuses][${i}][pipeline_id]`, mcfg.pipeline_id);
    addParam(`filter[statuses][${i}][status_id]`, s.id);
  });
  agentIds.forEach((id, i) => addParam(`filter[responsible_user_id][${i}]`, id));
  if (body.date_from && body.date_to) {
    addParam('filter[created_at][from]', toUnixStart(body.date_from));
    addParam('filter[created_at][to]', toUnixEnd(body.date_to));
  }

  let nextUrl = `https://${cfg.kommo_subdomain}.kommo.com/api/v4/leads?${qp.join('&')}`;
  let leadsEmbudo = [];
  let guard = 0;
  while (nextUrl && guard < 50) {
    let resp = await this.helpers.httpRequest({
      method: 'GET',
      url: nextUrl,
      headers: { Authorization: `Bearer ${cfg.kommo_token}`, 'Content-Type': 'application/json' },
      json: true,
    });
    // Kommo regresa 204 sin cuerpo cuando no hay resultados.
    if (!resp || typeof resp !== 'object') resp = {};
    leadsEmbudo = leadsEmbudo.concat((resp._embedded && resp._embedded.leads) || []);
    nextUrl = (resp._links && resp._links.next && resp._links.next.href) || null;
    guard++;
  }

  if (tagFilterSet) {
    leadsEmbudo = leadsEmbudo.filter(l => ((l._embedded && l._embedded.tags) || []).some(t => tagFilterSet.has(Number(t.id))));
  }

  const conteoPorEtapa = {};
  for (const l of leadsEmbudo) conteoPorEtapa[l.status_id] = (conteoPorEtapa[l.status_id] || 0) + 1;

  resultado[key] = {
    embudo: key,
    pipeline_id: mcfg.pipeline_id,
    leads_calificados: leadsEmbudo.length,
    monto_calificado: leadsEmbudo.reduce((sum, l) => sum + (l.price || 0), 0),
    por_etapa: mcfg.calientes.map(s => ({ etapa_id: s.id, etapa: s.nombre, leads: conteoPorEtapa[s.id] || 0 })),
  };
  for (const lead of leadsEmbudo) detalleRaw.push({ lead, embudoKey: key, mcfg });
}

// Nombre y correo del contacto principal (mismo patron que el resto del flujo: lookup por lote)
const contactIds = new Set();
for (const { lead } of detalleRaw) {
  const contactos = (lead._embedded && lead._embedded.contacts) || [];
  const principal = contactos.find(c => c.is_main) || contactos[0];
  if (principal) contactIds.add(principal.id);
}

async function fetchContactosPorId(idsSet) {
  const ids = [...idsSet];
  const out = {};
  if (!ids.length) return out;
  const BATCH = 100;
  for (let i = 0; i < ids.length; i += BATCH) {
    const batch = ids.slice(i, i + BATCH);
    const qp2 = batch.map((id, idx) => `filter%5Bid%5D%5B${idx}%5D=${id}`).join('&');
    const url = `https://${cfg.kommo_subdomain}.kommo.com/api/v4/contacts?${qp2}&limit=250`;
    let resp = await this.helpers.httpRequest({
      method: 'GET', url,
      headers: { Authorization: `Bearer ${cfg.kommo_token}`, 'Content-Type': 'application/json' },
      json: true,
    });
    if (!resp || typeof resp !== 'object') resp = {};
    for (const it of ((resp._embedded && resp._embedded.contacts) || [])) {
      const campoEmail = (it.custom_fields_values || []).find(f => f.field_code === 'EMAIL');
      const correo = (campoEmail && campoEmail.values && campoEmail.values[0] && campoEmail.values[0].value) || null;
      out[it.id] = { name: it.name, correo };
    }
  }
  return out;
}

const contactos = await fetchContactosPorId.call(this, contactIds);

const detalle = detalleRaw.map(({ lead, embudoKey, mcfg }) => {
  const cs = (lead._embedded && lead._embedded.contacts) || [];
  const principal = cs.find(c => c.is_main) || cs[0];
  const info = principal ? contactos[principal.id] : null;
  const idxEtapa = mcfg.calientes.findIndex(s => s.id === lead.status_id);
  return {
    lead_id: lead.id,
    nombre: (info && info.name) || lead.name || `Lead ${lead.id}`,
    correo: (info && info.correo) || null,
    embudo: embudoKey,
    monto: lead.price || 0,
    etapa: idxEtapa >= 0 ? mcfg.calientes[idxEtapa].nombre : null,
    etapa_orden: idxEtapa,
    responsible_user_id: lead.responsible_user_id || null,
    actualizado: lead.updated_at || null,
  };
}).sort((a, b) => a.embudo.localeCompare(b.embudo) || (b.etapa_orden - a.etapa_orden) || ((a.actualizado || 0) - (b.actualizado || 0)));

const totales = Object.values(resultado).reduce((acc, e) => {
  acc.leads_calificados += e.leads_calificados;
  acc.monto_calificado += e.monto_calificado;
  return acc;
}, { leads_calificados: 0, monto_calificado: 0 });

return [{ json: {
  periodo: (body.date_from && body.date_to) ? { from: body.date_from, to: body.date_to } : 'snapshot_actual_sin_filtro_de_fecha',
  por_embudo: resultado,
  totales,
  embudos_excluidos_sin_etapa_calificado: embudosExcluidos,
  leads_calificados_detalle: detalle,
}}];

// Lee body, config de Kommo y el mapeo de embudos
const body = $('Webhook3').first().json.body;
const cfg = $('Config4').first().json;
const mapeo = $('Config Mapeo2').first().json.embudos;

if (!body || body.type !== 'leads' || body.view !== 'response_times') {
  throw new Error(`Se esperaba type='leads' y view='response_times' pero llego type='${body && body.type}', view='${body && body.view}'.`);
}
if (!body.date_from || !body.date_to) {
  throw new Error('Faltan date_from/date_to en la solicitud.');
}

function toUnixStart(dateStr) { return Math.floor(new Date(`${dateStr}T00:00:00-06:00`).getTime() / 1000); }
function toUnixEnd(dateStr)   { return Math.floor(new Date(`${dateStr}T23:59:59-06:00`).getTime() / 1000); }

const fromTs = toUnixStart(body.date_from);
const toTs   = toUnixEnd(body.date_to);

function buildHeaders() {
  return { Authorization: `Bearer ${cfg.kommo_token}`, 'Content-Type': 'application/json' };
}

// ---------------------------------------------------------------------------
// HORARIO LABORAL: lunes a viernes, 9:00-18:00, hora local UTC-6 fija
// (Mexico, sin horario de verano -- mismo criterio
// que ya usa el resto del flujo). Parametrizado explicitamente por el cliente.
// ---------------------------------------------------------------------------
const TZ_OFFSET_SECONDS = -6 * 3600;
const DAY_SECONDS = 86400;
const BIZ_START_HOUR = 9;
const BIZ_END_HOUR = 18;

function businessSecondsBetween(startTs, endTs) {
  if (endTs == null || startTs == null || endTs <= startTs) return 0;
  const localStart = startTs + TZ_OFFSET_SECONDS;
  const localEnd = endTs + TZ_OFFSET_SECONDS;
  let dayCursor = Math.floor(localStart / DAY_SECONDS) * DAY_SECONDS;
  let total = 0;
  let guard = 0;
  while (dayCursor < localEnd && guard < 3660) {
    const dow = new Date(dayCursor * 1000).getUTCDay();
    if (dow >= 1 && dow <= 5) {
      const bizOpen = dayCursor + BIZ_START_HOUR * 3600;
      const bizClose = dayCursor + BIZ_END_HOUR * 3600;
      const overlapStart = Math.max(localStart, bizOpen);
      const overlapEnd = Math.min(localEnd, bizClose);
      if (overlapEnd > overlapStart) total += (overlapEnd - overlapStart);
    }
    dayCursor += DAY_SECONDS;
    guard++;
  }
  return total;
}

// PASO 1 - Leads creados en el periodo, con su contacto vinculado.
const qp = [];
function addParam(k, v) { qp.push(encodeURIComponent(k) + '=' + encodeURIComponent(v)); }
addParam('limit', '250');
addParam('with', 'contacts');
addParam('filter[created_at][from]', fromTs);
addParam('filter[created_at][to]', toTs);
// Solo se miden los embudos con tiempos != false (Push es difusion saliente: ahi el primer mensaje lo manda el sistema).
const permitidos = Object.values(mapeo).filter(m => m.tiempos !== false).map(m => m.pipeline_id);
const pidsFiltro = (body.pipeline_ids && body.pipeline_ids.length)
  ? body.pipeline_ids.map(Number).filter(id => permitidos.includes(id))
  : permitidos;
if (!pidsFiltro.length) {
  return [{ json: { periodo: { from: body.date_from, to: body.date_to }, por_embudo: {}, nota_metodologica: 'Los embudos elegidos no entran en la medicion de tiempos de respuesta (Push es difusion saliente).' } }];
}
pidsFiltro.forEach(id => addParam('filter[pipeline_id][]', id));

let nextUrl = `https://${cfg.kommo_subdomain}.kommo.com/api/v4/leads?${qp.join('&')}`;
let allLeads = [];
let guard = 0;
while (nextUrl && guard < 50) {
  let resp = await this.helpers.httpRequest({ method: 'GET', url: nextUrl, headers: buildHeaders(), json: true });
  if (!resp || typeof resp !== 'object') resp = {};
  const page = (resp._embedded && resp._embedded.leads) || [];
  allLeads = allLeads.concat(page);
  nextUrl = (resp._links && resp._links.next && resp._links.next.href) || null;
  guard++;
}

// leadsPorContacto: contact_id -> [leads de ESTE lote que comparten ese contacto]
// (normalmente 1, pero un contacto puede repetirse si es cliente recurrente)
const leadsPorContacto = {};
const contactIdsUnicos = new Set();
for (const lead of allLeads) {
  const contactos = (lead._embedded && lead._embedded.contacts) || [];
  if (!contactos.length) continue;
  const cid = contactos[0].id;
  contactIdsUnicos.add(cid);
  (leadsPorContacto[cid] = leadsPorContacto[cid] || []).push(lead);
}

// ---------------------------------------------------------------------------
// Primer contacto real = el primero que ocurra entre (a) mensaje saliente del
// asesor/bot o (b) llamada saliente -- a veces se llama antes de escribir.
// Ambos se piden juntos via /api/v4/events con filter[entity]=contact.
//
// OJO -- Kommo etiqueta cada tipo distinto en la respuesta (confirmado contra
// la cuenta real):
//  - outgoing_chat_message: entity_type='lead', entity_id=<id del lead> ya
//    resuelto por Kommo (viene del "talk" vinculado al lead activo).
//  - outgoing_call: entity_type='contact', entity_id=<id del CONTACTO> -- aqui
//    si hay que resolver nosotros a que lead corresponde, usando el lead mas
//    reciente de ese contacto creado antes o al momento de la llamada.
// ---------------------------------------------------------------------------
async function fetchPrimerContacto(contactIds) {
  const ids = [...contactIds];
  if (!ids.length) return [];
  const out = [];
  const BATCH = 10; // filter[entity_id] acepta max 10 ids por string, igual que el resto del flujo
  for (let i = 0; i < ids.length; i += BATCH) {
    const batch = ids.slice(i, i + BATCH);
    const eqp = [];
    function addE(k, v) { eqp.push(encodeURIComponent(k) + '=' + encodeURIComponent(v)); }
    addE('filter[type][0]', 'outgoing_chat_message');
    addE('filter[type][1]', 'outgoing_call');
    addE('filter[entity]', 'contact');
    addE('filter[entity_id]', batch.join(','));
    addE('limit', '250');
    let url = `https://${cfg.kommo_subdomain}.kommo.com/api/v4/events?${eqp.join('&')}`;
    let guard2 = 0;
    while (url && guard2 < 50) {
      let resp = await this.helpers.httpRequest({ method: 'GET', url, headers: buildHeaders(), json: true });
      if (!resp || typeof resp !== 'object') resp = {};
      const page = (resp._embedded && resp._embedded.events) || [];
      out.push(...page);
      url = (resp._links && resp._links.next && resp._links.next.href) || null;
      guard2++;
    }
  }
  return out;
}

const eventosContacto = await fetchPrimerContacto.call(this, contactIdsUnicos);

const primeraSalidaPorLead = {};
function considerar(leadId, ts) {
  if (ts == null || leadId == null) return;
  if (primeraSalidaPorLead[leadId] == null || ts < primeraSalidaPorLead[leadId]) {
    primeraSalidaPorLead[leadId] = ts;
  }
}

for (const ev of eventosContacto) {
  const ts = ev.created_at;
  if (ts == null) continue;
  if (ev.entity_type === 'lead' && ev.entity_id != null) {
    // Mensajes: Kommo ya resuelve el lead directamente
    considerar(ev.entity_id, ts);
  } else if (ev.entity_type === 'contact' && ev.entity_id != null) {
    // Llamadas: vienen etiquetadas al contacto, se resuelve al lead mas
    // reciente de ese contacto que ya existia al momento de la llamada.
    const candidatos = (leadsPorContacto[ev.entity_id] || []).filter(l => l.created_at <= ts);
    if (!candidatos.length) continue;
    candidatos.sort((a, b) => b.created_at - a.created_at);
    considerar(candidatos[0].id, ts);
  }
}

// PASO 2 - Agrupar por embudo y promediar (tiempo real Y tiempo en horario laboral)
const pipelineIdToKey = {};
for (const [key, mcfg] of Object.entries(mapeo)) pipelineIdToKey[mcfg.pipeline_id] = key;

const resultado = {};
for (const [key, mcfg] of Object.entries(mapeo)) {
  if (body.pipeline_ids && body.pipeline_ids.length && !body.pipeline_ids.includes(mcfg.pipeline_id)) continue;
  if (mcfg.tiempos === false) continue;
  resultado[key] = {
    embudo: key,
    pipeline_id: mcfg.pipeline_id,
    leads_entrantes: 0,
    leads_con_respuesta: 0,
    leads_pendientes: 0,
    promedio_segundos_habiles: 0,
    promedio_segundos_real: 0,
  };
}

const sumaHabilesPorEmbudo = {};
const sumaRealPorEmbudo = {};
for (const lead of allLeads) {
  const key = pipelineIdToKey[lead.pipeline_id];
  const entry = key && resultado[key];
  if (!entry) continue;
  entry.leads_entrantes++;

  const primeraTs = primeraSalidaPorLead[lead.id];
  if (primeraTs == null) { entry.leads_pendientes++; continue; }

  // Si el primer contacto ocurrio antes de que el lead quedara formalmente
  // creado (contacto con conversacion ya abierta), cuenta como respuesta
  // inmediata (0s) en vez de descartarse.
  const deltaReal = Math.max(0, primeraTs - lead.created_at);
  const deltaHabil = businessSecondsBetween(lead.created_at, primeraTs);

  entry.leads_con_respuesta++;
  sumaRealPorEmbudo[key] = (sumaRealPorEmbudo[key] || 0) + deltaReal;
  sumaHabilesPorEmbudo[key] = (sumaHabilesPorEmbudo[key] || 0) + deltaHabil;
}

for (const [key, entry] of Object.entries(resultado)) {
  entry.promedio_segundos_real = entry.leads_con_respuesta ? Math.round(sumaRealPorEmbudo[key] / entry.leads_con_respuesta) : 0;
  entry.promedio_segundos_habiles = entry.leads_con_respuesta ? Math.round(sumaHabilesPorEmbudo[key] / entry.leads_con_respuesta) : 0;
}

return [{ json: {
  periodo: { from: body.date_from, to: body.date_to },
  por_embudo: resultado,
  nota_metodologica: 'Hora entrante = created_at nativo del lead. Primera respuesta = el primero que ocurra entre el primer outgoing_chat_message o la primera outgoing_call asociados a ese lead (via /api/v4/events sobre el contacto vinculado). El promedio principal (promedio_segundos_habiles) solo cuenta segundos dentro de horario laboral lunes a viernes 9:00-18:00 hora local (UTC-6 fijo); promedio_segundos_real es el tiempo de reloj sin ajustar, de referencia. leads_pendientes queda en el JSON como referencia interna pero ya no se muestra como columna en el dashboard. Solo se miden los embudos de entrada (Embudo general y Pull); Push es difusion saliente, ahi el primer mensaje lo manda el sistema. Las respuestas del agente de IA cuentan como primera respuesta.'
}}];

// Leads vivos por embudo: mismo criterio que el filtro "Leads activos" de Kommo
// (todo lo que NO esta en Ganado (142) ni en Perdido/Cerrado (143)). Foto actual,
// sin filtro de fechas. Lee los embudos y etapas en vivo de Kommo, asi que cubre
// embudos nuevos sin tocar Config Mapeo.
const body = $('Webhook3').first().json.body;
const cfg = $('Config4').first().json;

if (!body || body.type !== 'leads' || body.view !== 'live_leads') {
  throw new Error(`Se esperaba type="leads" y view="live_leads" pero llego type="${body && body.type}", view="${body && body.view}".`);
}

const headers = { Authorization: `Bearer ${cfg.kommo_token}`, 'Content-Type': 'application/json' };
const base = `https://${cfg.kommo_subdomain}.kommo.com/api/v4`;
const mapeoCfg = $('Config Mapeo2').first().json.embudos;
const CERRADOS = new Set([142, 143]);
for (const m of Object.values(mapeoCfg)) { (m.ganado_ids || []).concat(m.perdido_ids || []).forEach(id => CERRADOS.add(id)); }

const httpGet = async (url) => {
  let resp = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
  // Kommo regresa 204 sin cuerpo cuando no hay resultados.
  if (!resp || typeof resp !== 'object') resp = {};
  return resp;
};

const pipelineFilter = (body.pipeline_ids && body.pipeline_ids.length) ? new Set(body.pipeline_ids.map(Number)) : null;
const agentIds = (body.agent_ids || []).map(Number);
const tagFilterSet = (body.tag_ids && body.tag_ids.length) ? new Set(body.tag_ids.map(Number)) : null;

const respPipelines = await httpGet(`${base}/leads/pipelines`);
const pipelines = ((respPipelines._embedded && respPipelines._embedded.pipelines) || [])
  .filter(p => !pipelineFilter || pipelineFilter.has(Number(p.id)))
  .sort((a, b) => (a.sort || 0) - (b.sort || 0));

const porEmbudo = {};
let totalLeadsVivos = 0;

for (const p of pipelines) {
  const etapas = ((p._embedded && p._embedded.statuses) || [])
    .filter(s => !CERRADOS.has(s.id));

  let leads = [];
  if (etapas.length) {
    const qp = [];
    const add = (k, v) => qp.push(encodeURIComponent(k) + '=' + encodeURIComponent(v));
    add('limit', '250');
    if (tagFilterSet) add('with', 'tags');
    etapas.forEach((s, i) => {
      add(`filter[statuses][${i}][pipeline_id]`, p.id);
      add(`filter[statuses][${i}][status_id]`, s.id);
    });
    agentIds.forEach((id, i) => add(`filter[responsible_user_id][${i}]`, id));

    let nextUrl = `${base}/leads?${qp.join('&')}`;
    let guard = 0;
    while (nextUrl && guard < 100) {
      const resp = await httpGet(nextUrl);
      leads = leads.concat((resp._embedded && resp._embedded.leads) || []);
      nextUrl = (resp._links && resp._links.next && resp._links.next.href) || null;
      guard++;
    }
  }

  if (tagFilterSet) {
    leads = leads.filter(l => ((l._embedded && l._embedded.tags) || []).some(t => tagFilterSet.has(Number(t.id))));
  }

  const conteoPorEtapa = {};
  for (const l of leads) conteoPorEtapa[l.status_id] = (conteoPorEtapa[l.status_id] || 0) + 1;

  porEmbudo[p.id] = {
    embudo_id: p.id,
    embudo: p.name,
    leads_vivos: leads.length,
    por_etapa: etapas.map(s => ({ etapa_id: s.id, etapa: s.name, leads: conteoPorEtapa[s.id] || 0 })),
  };
  totalLeadsVivos += leads.length;
}

return [{ json: {
  criterio: 'etapas activas (excluye Inscrito/Ganado y Descartado/Perdido), foto actual',
  por_embudo: porEmbudo,
  total_leads_vivos: totalLeadsVivos,
}}];

// Actividad diaria por asesor SIN Twilio: mensajes de WhatsApp enviados por una persona desde Kommo,
// notas, tareas completadas y citas (tareas de tipo "Reunión" con fecha dentro del periodo).
// Los mensajes del bot/automatizaciones salen con created_by = 0, asi que no se mezclan con los de las personas.
const body = $('Webhook3').first().json.body;
