};

// Usuarios: todos menos los excluidos del mapeo (p. ej. Educacion continua); si el dashboard
// eligio agentes, solo esos.
const respUsers = await httpGet(`${base}/users?limit=250`);
const excluidos = (conf.usuarios_excluidos || []).map(Number);
const usuarios = ((respUsers._embedded && respUsers._embedded.users) || []).filter(u => !excluidos.includes(Number(u.id)));
const pedidos = (body.agent_ids || []).map(Number);
const objetivo = pedidos.length ? usuarios.filter(u => pedidos.includes(Number(u.id))) : usuarios;

const TIPOS = { outgoing_chat_message: 'wa', common_note_added: 'notas', task_completed: 'tareas' };
const porAsesor = {};
const porDia = {};
const porDiaAsesor = {};

function sumarDia(dia, uid, clave) {
  if (!porDia[dia]) porDia[dia] = { fecha: dia, wa: 0, notas: 0, tareas: 0, citas: 0 };
  porDia[dia][clave]++;
  if (!porDiaAsesor[dia]) porDiaAsesor[dia] = {};
  porDiaAsesor[dia][uid] = (porDiaAsesor[dia][uid] || 0) + (clave === 'citas' ? 0 : 1);
}

for (const u of objetivo) {
  const acc = { agent_id: u.id, nombre: u.name, wa: 0, notas: 0, tareas: 0, citas_programadas: 0, citas_cumplidas: 0, total: 0 };
  porAsesor[u.id] = acc;

  const qp = [];
  const add = (k, v) => qp.push(encodeURIComponent(k) + '=' + encodeURIComponent(v));
  Object.keys(TIPOS).forEach((t, i) => add(`filter[type][${i}]`, t));
  add('filter[created_by][0]', u.id);
  add('filter[created_at][from]', fromTs);
  add('filter[created_at][to]', toTs);
  add('limit', '100');

  let url = `${base}/events?${qp.join('&')}`;
  let guard = 0;
  while (url && guard < 60) {
    const r = await httpGet(url);
    for (const e of ((r._embedded && r._embedded.events) || [])) {
      const clave = TIPOS[e.type];
      if (!clave) continue;
      acc[clave]++;
      acc.total++;
      sumarDia(diaLocal(e.created_at), u.id, clave);
    }
    url = (r._links && r._links.next && r._links.next.href) || null;
    guard++;
  }
}

// Citas = tareas de tipo "Reunion" (en esta cuenta: task_type 2) cuya fecha limite cae en el periodo.
// El filtro de fechas de /tasks no existe para complete_till, asi que se trae el tipo completo (pocas) y se filtra aqui.
const tipoCita = conf.tarea_tipo_cita != null ? conf.tarea_tipo_cita : 2;
let tareas = [];
let urlT = `${base}/tasks?filter[task_type][]=${tipoCita}&limit=250`;
