while (urlT && guardT < 20) {
  const r = await httpGet(urlT);
  tareas = tareas.concat((r._embedded && r._embedded.tasks) || []);
  urlT = (r._links && r._links.next && r._links.next.href) || null;
  guardT++;
}
for (const t of tareas) {
  if (!t.complete_till || t.complete_till < fromTs || t.complete_till > toTs) continue;
  const acc = porAsesor[t.responsible_user_id];
  if (!acc) continue;
  acc.citas_programadas++;
  if (t.is_completed) acc.citas_cumplidas++;
