}

return [{ json: {
  periodo: { from: body.date_from, to: body.date_to },
  por_asesor: porAsesor,
  por_dia: Object.values(porDia).sort((a, b) => a.fecha.localeCompare(b.fecha)),
  por_dia_asesor: porDiaAsesor,
  nota_metodologica: 'WhatsApp = mensajes salientes enviados por una persona desde Kommo (los del bot y las automatizaciones no cuentan; lo que se escribe desde el telefono fuera de Kommo tampoco aparece). Notas = notas escritas en el lead/contacto. Tareas = tareas completadas. Citas = tareas de tipo Reunion con fecha dentro del periodo (la cumplida es la que se marco como completada). Una cita cumplida tambien suma como tarea completada, por eso el total del dia no incluye las citas.',
}}];

// INDEMO · leads por asesora + atencion (gerente de ventas, indicadores base de Manu).
// Dos modos (body.modo):
//  'ia'       = lo que la IA (Valentina, SOLO redes sociales) delega: primera vez que un lead entra a CALIFICADO del embudo REDES SOCIALES.
//               El cambio de etapa hecho por el sistema (created_by = 0) cuenta como "delegado por la IA". Se mide cuanto tardan las asesoras en tocarlo.
//  'asesoras' = leads NUEVOS de los embudos CDMX y MTY (sin IA): todo corresponde a las asesoras. Se excluyen los que pasaron por el embudo de la IA.
const body = $('Webhook3').first().json.body;
const cfg = $('Config4').first().json;
const conf = $('Config Mapeo2').first().json;
const mapeo = conf.embudos;

if (!body || body.type !== 'leads' || body.view !== 'advisors') {
  throw new Error(`Se esperaba type="leads" y view="advisors" pero llego type="${body && body.type}", view="${body && body.view}".`);
}
if (!body.date_from || !body.date_to) {
  throw new Error('Faltan date_from/date_to en la solicitud.');
}
const MODO = body.modo === 'asesoras' ? 'asesoras' : 'ia';

// Horario laboral (configurable en Config Mapeo2). Por omision: lunes a viernes 9:00-18:00, hora de Ciudad de Mexico (UTC-6 fijo).
const HOR = conf.horario || { tz: -6, ini: 9, fin: 18, dias: [1, 2, 3, 4, 5] };
const TZ_OFFSET_SECONDS = HOR.tz * 3600;
const DAY_SECONDS = 86400;
function businessSecondsBetween(startTs, endTs) {
  if (endTs == null || startTs == null || endTs <= startTs) return 0;
  const localStart = startTs + TZ_OFFSET_SECONDS;
  const localEnd = endTs + TZ_OFFSET_SECONDS;
  let dayCursor = Math.floor(localStart / DAY_SECONDS) * DAY_SECONDS;
  let total = 0;
  let guard = 0;
  while (dayCursor < localEnd && guard < 3660) {
    const dow = new Date(dayCursor * 1000).getUTCDay();
    if (HOR.dias.includes(dow)) {
      const bizOpen = dayCursor + HOR.ini * 3600;
      const bizClose = dayCursor + HOR.fin * 3600;
      const overlapStart = Math.max(localStart, bizOpen);
      const overlapEnd = Math.min(localEnd, bizClose);
      if (overlapEnd > overlapStart) total += (overlapEnd - overlapStart);
    }
    dayCursor += DAY_SECONDS;
    guard++;
  }
  return total;
}

const tzTxt = (HOR.tz < 0 ? '-' : '+') + String(Math.abs(HOR.tz)).padStart(2, '0') + ':00';
const toStart = (d) => Math.floor(new Date(`${d}T00:00:00${tzTxt}`).getTime() / 1000);
const toEnd = (d) => Math.floor(new Date(`${d}T23:59:59${tzTxt}`).getTime() / 1000);
const fromTs = toStart(body.date_from);
const toTs = toEnd(body.date_to);
const ahora = Math.floor(Date.now() / 1000);
const LOOKBACK = (conf.lookback_dias || 180) * DAY_SECONDS;
const UMBRAL = (conf.umbral_sin_atender_horas || 24) * 3600;
const MAX_ATENCION = 1000;   // tope de leads a los que se les revisa la atencion (cada 10 leads = 2 peticiones a Kommo)
const CONCURRENCIA = 2;      // (las dos secciones corren a la vez en la pagina) Kommo limita ~7 peticiones por segundo y el token se comparte con el agente de la cuenta

const headers = { Authorization: `Bearer ${cfg.kommo_token}`, 'Content-Type': 'application/json' };
const base = `https://${cfg.kommo_subdomain}.kommo.com/api/v4`;
const dormir = (ms) => new Promise((r) => setTimeout(r, ms));
const httpGet = async (url) => {
  for (let intento = 0; ; intento++) {
    try {
      let resp = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
      // Kommo regresa 204 sin cuerpo cuando no hay resultados.
      if (!resp || typeof resp !== 'object') resp = {};
      return resp;
    } catch (e) {
      const txt = String((e && e.message) || '');
      const reintentable = txt.includes('429') || (e && (e.httpCode == 429 || e.statusCode == 429)) || /ECONNRESET|ETIMEDOUT|socket hang up/i.test(txt);
      if (!reintentable || intento >= 4) throw e;
      await dormir(1500 * (intento + 1));
    }
  }
};
const paginar = async (url, clave, tope) => {
  const out = [];
  let u = url;
  let g = 0;
  while (u && g < tope) {
    const r = await httpGet(u);
    out.push(...((r._embedded && r._embedded[clave]) || []));
    u = (r._links && r._links.next && r._links.next.href) || null;
    g++;
  }
  return out;
};
const agregar = (qp) => (k, v) => qp.push(encodeURIComponent(k) + '=' + encodeURIComponent(v));
// Corre fn sobre cada elemento con a lo mas n peticiones a la vez
const enParalelo = async (items, n, fn) => {
  let i = 0;
  const trabajadores = Array.from({ length: Math.min(n, items.length) }, async () => {
    while (i < items.length) { const k = i++; await fn(items[k], k); }
  });
  await Promise.all(trabajadores);
};

// Canales (por etiqueta del lead; la primera coincidencia gana)
const canalesCfg = conf.canales || [];
const nombreCanal = { sin_canal: 'Sin etiqueta de canal' };
canalesCfg.forEach(c => { nombreCanal[c.clave] = c.nombre; });
function canalDeLead(lead) {
  const tags = ((lead._embedded && lead._embedded.tags) || []).map(t => String(t.name));
  const bajas = tags.map(t => t.toLowerCase());
  for (const c of canalesCfg) {
    const nombres = (c.etiquetas || []).map(x => String(x).toLowerCase());
    const pats = (c.patrones || []).map(p => new RegExp(p, 'i'));
    if (bajas.some(t => nombres.includes(t)) || tags.some(t => pats.some(re => re.test(t)))) return c.clave;
  }
  return 'sin_canal';
}

// Filtros del dashboard
const pipelineIds = (body.pipeline_ids || []).map(Number);
const agentIds = (body.agent_ids || []).map(Number);
const tagFilterSet = (body.tag_ids && body.tag_ids.length) ? new Set(body.tag_ids.map(Number)) : null;
const excluidos = (conf.usuarios_excluidos || []).map(Number);
const claveDe = {};
for (const [k, m] of Object.entries(mapeo)) claveDe[m.pipeline_id] = k;
const clavesIA = Object.entries(mapeo).filter(([k, m]) => m.rol === 'ia').map(([k]) => k);
const clavesAs = Object.entries(mapeo).filter(([k, m]) => m.rol !== 'ia').map(([k]) => k);
// En el modo asesoras se cuentan los embudos elegidos (o todos los de asesoras si no se eligio ninguno de ellos)
let selAs = clavesAs.filter(k => !pipelineIds.length || pipelineIds.includes(Number(mapeo[k].pipeline_id)));
if (!selAs.length) selAs = clavesAs.slice();

// Usuarios: "persona" = cualquiera que no sea un usuario excluido (el bot y las automatizaciones salen con created_by = 0)
const users = await paginar(`${base}/users?limit=250`, 'users', 3);
const nombreUsuario = {};
users.forEach(u => { nombreUsuario[u.id] = u.name; });
const personas = users.map(u => Number(u.id)).filter(id => !excluidos.includes(id));

// Posiciones de etapa, nombres y etapas de entrada
const posDe = {};
const nombreEtapaDe = {};
const calientesDe = {};
for (const m of Object.values(mapeo)) {
  posDe[m.pipeline_id] = {};
  (m.stage_order || []).forEach((sid, i) => { posDe[m.pipeline_id][sid] = i; });
  nombreEtapaDe[m.pipeline_id] = {};
  calientesDe[m.pipeline_id] = new Set((m.calientes || []).map(s => s.id));
  (m.calientes || []).forEach(s => { nombreEtapaDe[m.pipeline_id][s.id] = s.nombre; });
  Object.entries(m.nombres_etapas || {}).forEach(([sid, nom]) => { if (!nombreEtapaDe[m.pipeline_id][sid]) nombreEtapaDe[m.pipeline_id][sid] = nom; });
}
const abiertoEnEntrada = (pid, sid) => calientesDe[pid] && calientesDe[pid].has(sid);

// Pares (embudo, etapa) a vigilar en el historial
const entradasIA = new Set();      // CALIFICADO (+ inscrito) del embudo de la IA: de aqui sale la cohorte del modo 'ia'
const paresRedes = [];             // cualquier etapa del embudo de la IA (para saber que leads paso por ella)
for (const k of clavesIA) {
  const m = mapeo[k];
  (m.calientes || []).forEach(s => entradasIA.add(m.pipeline_id + '/' + s.id));
  (m.ganado_ids || []).forEach(sid => entradasIA.add(m.pipeline_id + '/' + sid));
  const todas = new Set([...(m.stage_order || []), ...(m.ganado_ids || []), ...(m.perdido_ids || [])]);
  todas.forEach(sid => paresRedes.push({ p: m.pipeline_id, s: sid }));
}
// Avance (de "programa de interes" en adelante, mas inscrito) de los embudos de asesoras
const paresProgreso = (claves) => {
  const out = [];
  for (const k of claves) {
    const m = mapeo[k];
    const desde = m.efectivo != null && posDe[m.pipeline_id][m.efectivo] != null ? posDe[m.pipeline_id][m.efectivo] : 0;
    const ids = new Set([...(m.stage_order || []).slice(desde), ...(m.ganado_ids || [])]);
    ids.forEach(sid => out.push({ p: m.pipeline_id, s: sid }));
  }
  return out;
};
const eventosEntrada = async (pares, desdeTs, hastaTs) => {
  const qe = [];
  const ae = agregar(qe);
  ae('filter[type][0]', 'lead_status_changed');
  ae('filter[created_at][from]', desdeTs);
  ae('filter[created_at][to]', hastaTs);
  pares.forEach((o, i) => {
    ae(`filter[value_after][leads_statuses][${i}][pipeline_id]`, o.p);
    ae(`filter[value_after][leads_statuses][${i}][status_id]`, o.s);
  });
  ae('limit', '100');
  return paginar(`${base}/events?${qe.join('&')}`, 'events', 100);
};
const registrarAvance = (maxPosEv, eventos) => {
  for (const e of eventos) {
    const id = e.entity_id;
    if (id == null) continue;
    const d = e.value_after && e.value_after[0] && e.value_after[0].lead_status;
    const pos = (d && posDe[d.pipeline_id]) ? posDe[d.pipeline_id][d.id] : null;
    if (pos != null && (maxPosEv[id] == null || pos > maxPosEv[id])) maxPosEv[id] = pos;
  }
};

// 1) Cohorte de leads
const entrada = {};      // lead_id -> { ts, by }
const maxPosEv = {};     // lead_id -> posicion mas avanzada alcanzada (segun historial)
let nuevosCuenta = 0;
let excluidosPorIA = 0;
let cohorteLeads = [];

const qWith = ['tags', 'contacts', 'loss_reason'];
if (MODO === 'ia') {
  // Leads que pasaron por el embudo de la IA y la PRIMERA vez que llegaron a CALIFICADO
  const evR = await eventosEntrada(paresRedes, fromTs - LOOKBACK, toTs);
  const primeraRecibido = {};
  const primeraEntrada = {};
  for (const e of evR) {
    const id = e.entity_id;
    if (id == null) continue;
    const d = e.value_after && e.value_after[0] && e.value_after[0].lead_status;
    if (!primeraRecibido[id] || e.created_at < primeraRecibido[id]) primeraRecibido[id] = e.created_at;
    if (d && entradasIA.has(d.pipeline_id + '/' + d.id)) {
      if (!primeraEntrada[id] || e.created_at < primeraEntrada[id].ts) primeraEntrada[id] = { ts: e.created_at, by: e.created_by || 0 };
    }
  }
  // Leads creados en el periodo directamente en el embudo de la IA
  const qn = [];
  const an = agregar(qn);
  an('limit', '250');
  an('filter[created_at][from]', fromTs);
  an('filter[created_at][to]', toTs);
  clavesIA.forEach(k => an('filter[pipeline_id][]', mapeo[k].pipeline_id));
  const nuevosRedes = await paginar(`${base}/leads?${qn.join('&')}`, 'leads', 60);
  const recibidos = new Set();
  for (const [id, ts] of Object.entries(primeraRecibido)) { if (ts >= fromTs && ts <= toTs) recibidos.add(String(id)); }
  nuevosRedes.forEach(l => recibidos.add(String(l.id)));
  nuevosCuenta = recibidos.size;

  for (const [id, v] of Object.entries(primeraEntrada)) { if (v.ts >= fromTs && v.ts <= toTs) entrada[id] = v; }
  for (const l of nuevosRedes) {
    if (!primeraEntrada[l.id] && abiertoEnEntrada(l.pipeline_id, l.status_id)) entrada[l.id] = { ts: l.created_at, by: l.created_by || 0 };
  }
  const idsCohorte = Object.keys(entrada);
  await enParalelo(Array.from({ length: Math.ceil(idsCohorte.length / 100) }, (_, i) => idsCohorte.slice(i * 100, i * 100 + 100)), CONCURRENCIA, async (lote) => {
    const q = ['limit=250', 'with=' + encodeURIComponent(qWith.join(','))];
    lote.forEach((id, k) => q.push(`filter%5Bid%5D%5B${k}%5D=${id}`));
    const r = await httpGet(`${base}/leads?${q.join('&')}`);
    cohorteLeads.push(...((r._embedded && r._embedded.leads) || []));
  });
  cohorteLeads = cohorteLeads.filter(l => !!claveDe[l.pipeline_id]);
  // Avance de los delegados dentro de CDMX / MTY (cita, proceso de pago, inscrito)
  if (idsCohorte.length) {
    const minTs = Math.min(...idsCohorte.map(id => entrada[id].ts));
    registrarAvance(maxPosEv, await eventosEntrada(paresProgreso(clavesAs), minTs, toTs));
  }
} else {
  // Leads nuevos de los embudos de asesoras, sin los que pasaron por la IA
  const evR = await eventosEntrada(paresRedes, fromTs, toTs);
  const viaIA = new Set(evR.map(e => String(e.entity_id)));
  const qn = [];
  const an = agregar(qn);
  an('limit', '250');
  an('with', qWith.join(','));
  an('filter[created_at][from]', fromTs);
  an('filter[created_at][to]', toTs);
  selAs.forEach(k => an('filter[pipeline_id][]', mapeo[k].pipeline_id));
  const nuevos = await paginar(`${base}/leads?${qn.join('&')}`, 'leads', 60);
  nuevosCuenta = nuevos.length;
  for (const l of nuevos) {
    if (viaIA.has(String(l.id))) { excluidosPorIA++; continue; }
    if (!claveDe[l.pipeline_id]) continue;
    cohorteLeads.push(l);
    entrada[l.id] = { ts: l.created_at, by: l.created_by || 0 };
  }
  registrarAvance(maxPosEv, await eventosEntrada(paresProgreso(selAs), fromTs, toTs));
}
const leadsExcluidos = new Set((conf.leads_excluidos || []).map(Number));   // leads de prueba del equipo (no son leads reales)
const cohorte = cohorteLeads.filter(l => !excluidos.includes(Number(l.responsible_user_id)) && !leadsExcluidos.has(Number(l.id))
  && (!agentIds.length || agentIds.includes(Number(l.responsible_user_id)))
  && (!tagFilterSet || ((l._embedded && l._embedded.tags) || []).some(t => tagFilterSet.has(Number(t.id)))));

// 2) Avance de cada lead (embudo donde esta HOY, asesora responsable y canal)
const porEmbudo = {};
const llavesEmbudo = MODO === 'ia' ? Object.keys(mapeo) : selAs;
for (const key of llavesEmbudo) {
  const m = mapeo[key];
  porEmbudo[key] = { embudo: key, pipeline_id: m.pipeline_id, llegaron: 0, delegados_ia: 0, propios: 0, cita: 0, docs: 0, ganado: 0, perdido: 0, monto_ganado: 0, motivos_perdida: {} };
}
const porAsesor = {};
const porCanal = {};
const registros = [];
for (const l of cohorte) {
  const key = claveDe[l.pipeline_id];
  const m = mapeo[key];
  const e = porEmbudo[key] || (porEmbudo[key] = { embudo: key, pipeline_id: m.pipeline_id, llegaron: 0, delegados_ia: 0, propios: 0, cita: 0, docs: 0, ganado: 0, perdido: 0, monto_ganado: 0, motivos_perdida: {} });
  const ent = entrada[l.id];
  const porIA = MODO === 'ia' && ent.by === 0;
  const ganado = (m.ganado_ids || []).includes(l.status_id);
  const perdido = (m.perdido_ids || []).includes(l.status_id);
  const pos = posDe[m.pipeline_id][l.status_id];
  const maxPos = Math.max(maxPosEv[l.id] != null ? maxPosEv[l.id] : -1, pos != null ? pos : -1);
  const posCita = m.calificado != null ? posDe[m.pipeline_id][m.calificado] : null;
  const posDocs = m.cotizacion != null ? posDe[m.pipeline_id][m.cotizacion] : null;
  const llegoCita = ganado || (posCita != null && maxPos >= posCita);
  const llegoDocs = ganado || (posDocs != null && maxPos >= posDocs);
  const uid = l.responsible_user_id || 0;

  e.llegaron++;
  if (porIA) e.delegados_ia++; else e.propios++;
  if (llegoCita) e.cita++;
  if (llegoDocs) e.docs++;
  if (ganado) { e.ganado++; e.monto_ganado += (l.price || 0); }
  if (perdido) {
    e.perdido++;
    const motivo = (l._embedded && l._embedded.loss_reason && l._embedded.loss_reason[0] && l._embedded.loss_reason[0].name) || 'Sin motivo registrado';
    e.motivos_perdida[motivo] = (e.motivos_perdida[motivo] || 0) + 1;
  }

  const a = porAsesor[uid] || (porAsesor[uid] = {
    agent_id: uid, nombre: nombreUsuario[uid] || ('Usuario ' + uid),
    llegaron: 0, delegados_ia: 0, propios: 0, cita: 0, docs: 0, ganado: 0, perdido: 0,
    atendidos: 0, sin_atender: 0, en_plazo: 0, fuera_de_hot: 0, seg_habiles: 0, seg_reales: 0, con_tiempo: 0,
    contactados: 0, seg_contacto: 0,
  });
  a.llegaron++;
  if (porIA) a.delegados_ia++; else a.propios++;
  if (llegoCita) a.cita++;
  if (llegoDocs) a.docs++;
  if (ganado) a.ganado++;
  if (perdido) a.perdido++;

  const ck = canalDeLead(l);
  const ch = porCanal[ck] || (porCanal[ck] = { clave: ck, nombre: nombreCanal[ck], leads: 0, citas: 0, inscritos: 0, monto: 0 });
  ch.leads++;
  if (llegoCita) ch.citas++;
  if (ganado) { ch.inscritos++; ch.monto += (l.price || 0); }

  registros.push({ l, key, ent, porIA, uid, ganado, perdido });
}

// 3) Atencion: despues de la entrega (IA) o de que el lead nace (asesoras), cuanto tarda una PERSONA en hacer algo
//    (mensaje, llamada, nota, tarea completada o mover la etapa). Se separa el primer toque de cualquier tipo del primer mensaje/llamada.
let paraAtender = MODO === 'ia' ? registros.filter(r => r.porIA) : registros.slice();
let atencionOmitidos = 0;
if (paraAtender.length > MAX_ATENCION) {
  paraAtender.sort((x, y) => y.ent.ts - x.ent.ts);
  atencionOmitidos = paraAtender.length - MAX_ATENCION;
  paraAtender = paraAtender.slice(0, MAX_ATENCION);
}
const accion = {};
const leadsDeContacto = {};
const contactoDeLead = {};
for (const r of paraAtender) {
  const cs = (r.l._embedded && r.l._embedded.contacts) || [];
  const principal = cs.find(c => c.is_main) || cs[0];
  if (principal) { contactoDeLead[r.l.id] = principal.id; (leadsDeContacto[principal.id] = leadsDeContacto[principal.id] || []).push(r.l.id); }
}
const marcar = (leadId, e) => { (accion[leadId] = accion[leadId] || []).push({ ts: e.created_at, by: e.created_by, tipo: e.type }); };
if (paraAtender.length && personas.length) {
  const minTs = Math.min(...paraAtender.map(r => r.ent.ts));
  const comunes = (qp) => {
    const a = agregar(qp);
    personas.forEach((h, i) => a(`filter[created_by][${i}]`, h));
    a('filter[created_at][from]', minTs);
    a('limit', '100');
    return a;
  };
  const tareas = [];
  const idsLead = paraAtender.map(r => r.l.id);
  for (let i = 0; i < idsLead.length; i += 10) tareas.push({ entidad: 'lead', ids: idsLead.slice(i, i + 10), tipos: ['common_note_added', 'task_completed', 'lead_status_changed'] });
  const idsContacto = Object.keys(leadsDeContacto);
  for (let i = 0; i < idsContacto.length; i += 10) tareas.push({ entidad: 'contact', ids: idsContacto.slice(i, i + 10), tipos: ['outgoing_chat_message', 'outgoing_call'] });
  await enParalelo(tareas, CONCURRENCIA, async (t) => {
    const qp = [];
    const a = agregar(qp);
    a('filter[entity]', t.entidad);
    a('filter[entity_id]', t.ids.join(','));
    t.tipos.forEach((tp, k) => a(`filter[type][${k}]`, tp));
    comunes(qp);
    const ev = await paginar(`${base}/events?${qp.join('&')}`, 'events', 10);
    for (const e of ev) {
      if (e.entity_type === 'lead') marcar(e.entity_id, e);
      else for (const lid of (leadsDeContacto[e.entity_id] || [])) marcar(lid, e);
    }
  });
}

const esMensaje = (x) => x.tipo === 'outgoing_chat_message' || x.tipo === 'outgoing_call';
const sinAtender = [];
for (const r of paraAtender) {
  const acc = (accion[r.l.id] || []).filter(x => x.ts > r.ent.ts).sort((x, y) => x.ts - y.ts);
  const primero = acc[0] || null;
  const primerMensaje = acc.find(esMensaje) || null;
  const a = porAsesor[r.uid];
  if (primero) {
    a.atendidos++;
    a.con_tiempo++;
    a.seg_habiles += businessSecondsBetween(r.ent.ts, primero.ts);
    a.seg_reales += (primero.ts - r.ent.ts);
    if (primerMensaje) { a.contactados++; a.seg_contacto += businessSecondsBetween(r.ent.ts, primerMensaje.ts); }
  } else if (MODO === 'ia' ? !abiertoEnEntrada(r.l.pipeline_id, r.l.status_id) && !r.ganado : (r.ganado || r.perdido)) {
    // IA: la IA lo delego y despues lo regreso a una etapa anterior o lo perdio sin que nadie lo tocara.
    // Asesoras: el lead ya se cerro (inscrito o perdido) sin que ninguna persona lo tocara.
    a.fuera_de_hot++;
  } else if (ahora - r.ent.ts >= UMBRAL) {
    a.sin_atender++;
    sinAtender.push({
      lead_id: r.l.id, lead: r.l.name || ('Lead ' + r.l.id), embudo: r.key,
      etapa: (nombreEtapaDe[r.l.pipeline_id] || {})[r.l.status_id] || ('Etapa ' + r.l.status_id),
      responsible_user_id: r.uid, entregado: r.ent.ts, otra_persona: false,
      contacto_id: contactoDeLead[r.l.id] || null,
    });
  } else {
    a.en_plazo++;
  }
}

// Nombre del contacto (solo para la lista de "sin atender")
sinAtender.sort((x, y) => x.entregado - y.entregado);
const visibles = sinAtender.slice(0, 200);
const idsNombres = [...new Set(visibles.map(s => s.contacto_id).filter(Boolean))];
const nombreContacto = {};
await enParalelo(Array.from({ length: Math.ceil(idsNombres.length / 100) }, (_, i) => idsNombres.slice(i * 100, i * 100 + 100)), CONCURRENCIA, async (lote) => {
  const q = ['limit=250'];
  lote.forEach((id, k) => q.push(`filter%5Bid%5D%5B${k}%5D=${id}`));
  const r = await httpGet(`${base}/contacts?${q.join('&')}`);
  for (const c of ((r._embedded && r._embedded.contacts) || [])) nombreContacto[c.id] = c.name;
});

// Historial de cada lead de la lista: que le paso y quien lo hizo (sin usuario = sistema/IA)
const historiales = {};
try {
  const nombreEtapaGlobal = {};
  const pl = await httpGet(`${base}/leads/pipelines`);
  for (const pp of ((pl._embedded && pl._embedded.pipelines) || [])) {
    for (const st of ((pp._embedded && pp._embedded.statuses) || [])) nombreEtapaGlobal[st.id] = String(st.name || '').trim();
  }
  Object.values(nombreEtapaDe).forEach(mm => Object.entries(mm).forEach(([sid, nom]) => { nombreEtapaGlobal[sid] = nom; }));
  const MAX_EVENTOS = 30;
  const porLead = {};
  const lotes = [];
  for (let i = 0; i < visibles.length; i += 10) lotes.push(visibles.slice(i, i + 10));
  await enParalelo(lotes, CONCURRENCIA, async (lote) => {
    const qh = [];
    const ah = agregar(qh);
    ah('filter[entity]', 'lead');
    ah('filter[entity_id]', lote.map(s => s.lead_id).join(','));
    ['lead_added', 'lead_status_changed', 'common_note_added', 'task_completed', 'entity_responsible_changed'].forEach((t, k) => ah(`filter[type][${k}]`, t));
    ah('limit', '100');
    const evh = await paginar(`${base}/events?${qh.join('&')}`, 'events', 6);
    for (const e of evh) (porLead[e.entity_id] = porLead[e.entity_id] || []).push(e);
  });
  const quien = (id) => (!id ? 'Sistema (IA o automatizacion)' : (nombreUsuario[id] || ('Usuario ' + id)));
  const etapaDe = (v) => { const d = v && v[0] && v[0].lead_status; return d ? (nombreEtapaGlobal[d.id] || ('Etapa ' + d.id)) : null; };
  const usuarioDe = (v) => { const d = v && v[0] && v[0].responsible_user; return d ? quien(d.id) : null; };
  for (const [lid, evs] of Object.entries(porLead)) {
    evs.sort((x, y) => x.created_at - y.created_at);
    const lista = evs.map(e => ({
      ts: e.created_at, tipo: e.type, por: quien(e.created_by), persona: !!e.created_by,
      de: e.type === 'lead_status_changed' ? etapaDe(e.value_before) : (e.type === 'entity_responsible_changed' ? usuarioDe(e.value_before) : null),
      a: e.type === 'lead_status_changed' ? etapaDe(e.value_after) : (e.type === 'entity_responsible_changed' ? usuarioDe(e.value_after) : null),
    }));
    historiales[lid] = { historial: lista.slice(-MAX_EVENTOS), historial_omitidos: Math.max(0, lista.length - MAX_EVENTOS) };
  }
} catch (err) { /* sin historial: el reporte sigue funcionando */ }
const listaSinAtender = visibles.map(s => ({
  lead_id: s.lead_id, nombre: (s.contacto_id && nombreContacto[s.contacto_id]) || s.lead, embudo: s.embudo, etapa: s.etapa,
  responsible_user_id: s.responsible_user_id, entregado: s.entregado, otra_persona: s.otra_persona,
  ...(historiales[s.lead_id] || { historial: [], historial_omitidos: 0 }),
}));

for (const a of Object.values(porAsesor)) {
  a.promedio_segundos_habiles = a.con_tiempo ? Math.round(a.seg_habiles / a.con_tiempo) : null;
  a.promedio_segundos_reales = a.con_tiempo ? Math.round(a.seg_reales / a.con_tiempo) : null;
  a.promedio_segundos_contacto = a.contactados ? Math.round(a.seg_contacto / a.contactados) : null;
  delete a.seg_habiles; delete a.seg_reales; delete a.seg_contacto;
}

const total = (campo) => Object.values(porAsesor).reduce((s, a) => s + (a[campo] || 0), 0);
const notaIA = 'Modo IA (redes sociales): un lead le toca a las asesoras cuando entra por primera vez a CALIFICADO del embudo REDES SOCIALES. Si el cambio de etapa lo hizo el sistema cuenta como delegado por la IA; si lo hizo una persona, como movido por una asesora. Atendido = alguien del equipo mando un WhatsApp, hizo una llamada, escribio una nota, completo una tarea o movio la etapa despues de la entrega (cualquier persona: en Indemo todo el equipo comparte pocos usuarios de Kommo). Sin atender = pasaron mas de ' + (UMBRAL / 3600) + ' h, sigue en CALIFICADO y nadie lo ha tocado. "Ya no estan en CALIFICADO" = la IA lo regreso a una etapa anterior o lo perdio sin que nadie lo tocara. "Dónde están hoy" cuenta la etapa y el embudo actuales de cada lead delegado (al avanzar pasan a CDMX o MTY).';
const notaAs = 'Modo asesoras (CDMX y MTY): se cuentan los leads CREADOS en el periodo en esos embudos; los que pasaron por el embudo de la IA (redes sociales) se excluyen y se ven en la otra pestaña. Atendido = alguien del equipo mando un WhatsApp, hizo una llamada, escribio una nota, completo una tarea o movio la etapa despues de que el lead nacio. Sin atender = pasaron mas de ' + (UMBRAL / 3600) + ' h y nadie lo ha tocado. "Cerrados sin que nadie los tocara" = ya estan en inscrito o perdido sin ninguna accion de una persona.';
return [{ json: {
  modo: MODO,
  periodo: { from: body.date_from, to: body.date_to },
  resumen_ia: {
    leads_nuevos: nuevosCuenta,
    delegados_ia: total('delegados_ia'),
    movidos_por_asesores: total('propios'),
    fuera_de_hot: total('fuera_de_hot'),
    excluidos_por_ia: excluidosPorIA,
    contactados: total('contactados'),
  },
  por_embudo: porEmbudo,
  por_asesor: porAsesor,
  por_canal: Object.values(porCanal).sort((a, b) => (b.inscritos - a.inscritos) || (b.leads - a.leads)),
  sin_atender: listaSinAtender,
  total_sin_atender: sinAtender.length,
  atencion_omitidos: atencionOmitidos,
  atencion_tope: MAX_ATENCION,
  umbral_horas: UMBRAL / 3600,
  zona_horas: TZ_OFFSET_SECONDS / 3600,
  horario: { ini: HOR.ini, fin: HOR.fin, dias: HOR.dias },
  nota_metodologica: MODO === 'ia' ? notaIA : notaAs,
}}];
